{-# LANGUAGE TemplateHaskell #-}
{-# OPTIONS_GHC -Wno-orphans #-}

-- | Example's export table, generated by uglyModule: module "Example" in
-- the library Example.so.
module Example.Ugly () where

import Example
import Ugly.Export

uglyModule "Example"
  [ ''Shape, ''Pt
  , 'Circle, 'Square, 'Pt, 'origin
  , 'area, 'scale, 'unit, 'largest, 'firstOf, 'label, 'mapPt
    -- polymorphic in the result alone: chosen by want, or a hint
  , 'read, 'minBound ]
